command -v python3>/dev/null||exit 127;python3 -c 'from fractions import Fraction as F;import sys,json as j,os,math;P=[2,3,5,7,11,13];f="state.json";o=j.load(open(f))if os.path.exists(f)and os.path.getsize(f)else{};t=o.get("tick",0)+1;a=list(map(int,sys.argv[1].split(",")))if len(sys.argv)>1 else [0]*6;assert len(a)==6;Z=lambda k:2*k if k>=0 else-2*k-1;U=lambda n:n//2 if n%2==0 else-(n+1)//2;V=lambda n,p:(lambda g:g(g,n,0))(lambda g,n,c:g(g,n//p,c+1)if n%p==0 else c);G=math.prod(p**(Z(k)+1)for p,k in zip(P,a));D=[U(V(G,p)-1)for p in P];N=math.prod(p**max(k,0)for p,k in zip(P,a));M=math.prod(p**max(-k,0)for p,k in zip(P,a));S=math.prod((F(p+1,p-1)for p in P),start=F(1));X={"model":"RIEMANN_GODEL_RATIONAL_SPECTRAL_HOLOGRAM_TM","tick":t,"primes":P,"space":"Z^6","k":a,"godel":str(G),"decode":D,"reversible":D==a,"rational":[N,M],"coprime":math.gcd(N,M)==1,"log_spectrum":["sum"]+[["mul",k,["log",p]]for p,k in zip(P,a)],"s1_partition":[S.numerator,S.denominator],"finite_formula":"prod_p((1+p^-s)/(1-p^-s))","all_prime_formula":"zeta(s)^2/zeta(2s), Re(s)>1","claims":{"all_Z6":True,"all_positive_rationals":False,"RH_proved":False}};b=j.dumps(X,sort_keys=True,separators=(",",":")).encode();Y={**X,"hologram":{"coeff":list(b),"reconstruct":j.loads(b.decode())==X},"exact":{"float":False,"sha":False}};open(f,"w").write(j.dumps(Y,separators=(",",":")));print(j.dumps(Y,separators=(",",":")))' "$@"